package io.github.jhipster.sample.service;

import io.github.jhipster.sample.repository.OperationRepository;
import io.github.jhipster.sample.service.dto.OperationDTO;
import java.time.Instant;
import java.time.temporal.ChronoUnit;
import org.springframework.data.domain.Page;
import org.springframework.data.domain.Pageable;
import org.springframework.stereotype.Service;
import org.springframework.transaction.annotation.Transactional;

/**
 * Service for operation queries that go beyond generated CRUD.
 */
@Service
@Transactional(readOnly = true)
public class OperationService {

    static final int RECENT_DAYS = 30;

    private final OperationRepository operationRepository;

    public OperationService(OperationRepository operationRepository) {
        this.operationRepository = operationRepository;
    }

    /**
     * Get the operations dated within the last {@value #RECENT_DAYS} days.
     *
     * @param pageable the pagination information.
     * @return the page of recent operations.
     */
    public Page<OperationDTO> findRecent(Pageable pageable) {
        Instant since = Instant.now().minus(RECENT_DAYS, ChronoUnit.DAYS);
        return operationRepository.findAllByDateGreaterThanEqual(since, pageable).map(OperationDTO::from);
    }
}
EOF
